import sys
input_matrix = [[int(x) for x in sys.stdin.readline().split()] for _ in range(n)]

matrix = [[int(x) for _ in range(m)] for _ in range(int(input())]

def findMaxPathSum(matrix):
    dp = [sys.maxsize for _ in range(m)]
    for i in range(n):
        for j in range(m):
            dp[i][j] = min(dp[i][j], dp[i-1][j] + matrix[i][j]
    return dp[n-1][m-1]

if __name__ == '__main__':
result = findMaxPathSum(input_matrix)
print(result)
